param(
  [ValidateSet('x86', 'x64')][string]$CompileArchitecture,
  [string]$SourceDirectory = (Join-Path (Split-Path $PSScriptRoot -Parent) '.deps/dxvk-remix'),
  [switch]$RunOnly,
  # Optional local validation only. CI defaults to the pinned MSVC toolset.
  [string]$MingwDirectory
)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$source = (Resolve-Path -LiteralPath $SourceDirectory).Path
$testDirectory = Join-Path $repoRoot '.deps/command-guard-test'
$support = Join-Path $repoRoot 'tests/command_guard_support'
$variants = @('current', 'seq_cst', 'relaxed')
$utf8 = [Text.UTF8Encoding]::new($false)
$files = @(
  'util_bridgecommand.cpp', 'util_bridgecommand.h', 'util_ipcchannel.h', 'util_atomiccircularqueue.h',
  'util_blockingcircularqueue.h', 'util_circularbuffer.h', 'util_circularqueue.h',
  'util_sharedmemory.h', 'util_sharedmemory.cpp', 'util_semaphore.h', 'util_semaphore.cpp',
  'util_guid.h', 'util_common.h', 'util_commands.h', 'util_bridge_state.h', 'util_singleton.h',
  'api_wait_diagnostics.h', 'queue_wait_diagnostics.h', 'runtime_observation.h',
  'exception_diagnostics.h', 'data_diagnostics.h', 'device_reset.h', 'data_ring_contract.h', 'log/log_strings.h'
)
$testSource = Join-Path $repoRoot 'tests/command_guard_ipc.cpp'
$harnessHash = (Get-FileHash -LiteralPath $testSource -Algorithm SHA256).Hash
if ($MingwDirectory) { $MingwDirectory = (Resolve-Path -LiteralPath $MingwDirectory).Path }
if ($RunOnly -and $CompileArchitecture) { throw 'RunOnly cannot be combined with CompileArchitecture' }
$supportHashes = [ordered]@{}
Get-ChildItem -LiteralPath $support -Recurse -File | Where-Object { $_.Extension -in @('.h', '.hpp', '.cpp') } | ForEach-Object {
  $supportHashes[$_.FullName.Substring($support.Length + 1)] = (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash
}

if (!$CompileArchitecture) {
  if (!$RunOnly) {
    foreach ($arch in @('x86', 'x64')) {
      $arguments = @('-NoProfile', '-File', $PSCommandPath, '-CompileArchitecture', $arch,
        '-SourceDirectory', $source)
      if ($MingwDirectory) { $arguments += @('-MingwDirectory', $MingwDirectory) }
      & powershell.exe @arguments
      if ($LASTEXITCODE -ne 0) { throw "Command guard compilation failed for $arch" }
    }
  }
  # Also check fresh builds: refuse stale/mixed binaries or source changed while
  # the other architecture compiled. RunOnly is safe only for identical inputs.
  $buildMode = $null
  foreach ($arch in @('x86', 'x64')) {
    foreach ($variant in $variants) {
      $build = Join-Path $testDirectory "$arch/$variant"
      $metadata = Get-Content -Raw -LiteralPath (Join-Path $build 'build-metadata.json') | ConvertFrom-Json
      if ($metadata.architecture -ne $arch -or $metadata.variant -ne $variant -or $metadata.source -ne $source) {
        throw "Mismatched Command guard build metadata: $arch / $variant"
      }
      if ((@($metadata.source_sha256.PSObject.Properties.Name | Sort-Object) -join "`n") -cne
          (@($files | Sort-Object) -join "`n") -or
          (@($metadata.support_sha256.PSObject.Properties.Name | Sort-Object) -join "`n") -cne
          (@($supportHashes.Keys | Sort-Object) -join "`n")) {
        throw "Command guard input file set changed or metadata is incomplete: $arch / $variant"
      }
      $mode = if ($metadata.mingw_header_adaptations) { 'mingw' } else { 'msvc' }
      if ($null -eq $buildMode) { $buildMode = $mode }
      elseif ($mode -ne $buildMode) { throw 'Command guard binaries mix MSVC and MinGW builds; rebuild both architectures' }
      foreach ($entry in $metadata.source_sha256.PSObject.Properties) {
        $actual = (Get-FileHash -LiteralPath (Join-Path $source "bridge/src/util/$($entry.Name)") -Algorithm SHA256).Hash
        if ($actual -ne $entry.Value) { throw "Production source changed; rebuild before running: $($entry.Name)" }
      }
      foreach ($file in $supportHashes.Keys) {
        if (!$metadata.support_sha256 -or $metadata.support_sha256.$file -ne $supportHashes[$file]) {
          throw "Command guard support changed; rebuild before running: $file"
        }
      }
      if ((Get-FileHash -LiteralPath $testSource -Algorithm SHA256).Hash -ne $harnessHash -or
          $harnessHash -ne $metadata.harness_sha256 -or
          (Get-FileHash -LiteralPath (Join-Path $build 'command-guard.exe') -Algorithm SHA256).Hash -ne $metadata.executable_sha256) {
        throw "Command guard executable or harness changed; rebuild before running: $arch / $variant"
      }
    }
  }
  $cases = @(@(1, 20000, 0, 0), @(1, 4096, 0, 1), @(4, 5000, 0, 1), @(4, 5000, 1, 1))
  $rows = [Collections.Generic.List[object]]::new()
  foreach ($variant in $variants) {
    $client = Join-Path $testDirectory "x86/$variant/command-guard.exe"
    $hostExecutable = Join-Path $testDirectory "x64/$variant/command-guard.exe"
    foreach ($case in $cases) {
      $result = @(& $client $hostExecutable @case)
      if ($LASTEXITCODE -ne 0) { throw "Command guard IPC failed: $variant / $($case -join ',')" }
      $row = ($result -join "`n") | ConvertFrom-Json
      if (!$row.pass) { throw "Command guard IPC returned no success: $variant" }
      $row | Add-Member -NotePropertyName variant -NotePropertyValue $variant
      $rows.Add($row)
      Write-Output ($row | ConvertTo-Json -Compress)
    }
  }
  $rows | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $testDirectory 'results.json') -Encoding UTF8
  Write-Output 'PASS: current, original seq_cst and relaxed guards; actual x86 Client / x64 Host Command and IPC; 12 scenarios'
  exit 0
}

$sourceUtil = Join-Path $source 'bridge/src/util'
$architectureDirectory = Join-Path $testDirectory $CompileArchitecture
New-Item -ItemType Directory -Force $architectureDirectory | Out-Null
if ($MingwDirectory) {
  $compilerName = if ($CompileArchitecture -eq 'x86') { 'i686-w64-mingw32-g++.exe' } else { 'g++.exe' }
  $compiler = (Resolve-Path -LiteralPath (Join-Path $MingwDirectory $compilerName)).Path
} else {
  . (Join-Path $source 'bridge/build_common.ps1')
  SetupVS -Platform $CompileArchitecture -VcVarsVer '14.29'
  $compiler = (Get-Command cl.exe -ErrorAction Stop).Source
}

$sourceHashes = [ordered]@{}
foreach ($file in $files) {
  $sourceHashes[$file] = (Get-FileHash -LiteralPath (Join-Path $sourceUtil $file) -Algorithm SHA256).Hash
}
$original = [IO.File]::ReadAllText((Join-Path $sourceUtil 'util_bridgecommand.cpp'))
$loadPattern = 'pbCmdInProgress->load\(\s*(?:std::memory_order_(?:seq_cst|relaxed)\s*)?\)'
$truePattern = 'pbCmdInProgress->store\(true\s*(?:,\s*std::memory_order_(?:seq_cst|relaxed)\s*)?\)'
$falsePattern = 'pbCmdInProgress->store\(false\s*(?:,\s*std::memory_order_(?:seq_cst|relaxed)\s*)?\)'
if ([regex]::Matches($original, $loadPattern).Count -ne 2 -or
    [regex]::Matches($original, $truePattern).Count -ne 1 -or
    [regex]::Matches($original, $falsePattern).Count -ne 1 -or
    [regex]::Matches($original, 'pbCmdInProgress->(?:load|store)\(').Count -ne 4) {
  throw 'Expected exactly two guard loads and true/false stores, with default, seq_cst or relaxed ordering'
}
function Mask-GuardOrder([string]$Text) {
  $Text = [regex]::Replace($Text, $loadPattern, 'pbCmdInProgress->load(GUARD_ORDER)')
  $Text = [regex]::Replace($Text, $truePattern, 'pbCmdInProgress->store(true, GUARD_ORDER)')
  return [regex]::Replace($Text, $falsePattern, 'pbCmdInProgress->store(false, GUARD_ORDER)')
}

foreach ($variant in $variants) {
  $output = Join-Path $architectureDirectory $variant
  $fixture = Join-Path $output 'source'
  $util = Join-Path $fixture 'util'
  foreach ($directory in @($output, $util, "$util/log", "$util/config", "$fixture/tracy")) {
    New-Item -ItemType Directory -Force $directory | Out-Null
  }
  foreach ($file in $files) {
    $destination = Join-Path $util $file
    Copy-Item -LiteralPath (Join-Path $sourceUtil $file) -Destination $destination -Force
    if ((Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash -ne $sourceHashes[$file]) {
      throw "Source changed while preparing fixture: $file"
    }
  }
  foreach ($file in @('config/global_options.h', 'log/log.h')) {
    Copy-Item -LiteralPath (Join-Path $support $file) -Destination (Join-Path $util $file) -Force
  }
  Copy-Item -LiteralPath (Join-Path $support 'tracy/tracy.hpp') -Destination (Join-Path $fixture 'tracy/tracy.hpp') -Force
  $commandFile = Join-Path $util 'util_bridgecommand.cpp'
  if ($variant -ne 'current') {
    $order = if ($variant -eq 'relaxed') { 'std::memory_order_relaxed' } else { '' }
    $storeOrder = if ($order) { ", $order" } else { '' }
    $candidate = [regex]::Replace($original, $loadPattern, "pbCmdInProgress->load($order)")
    $candidate = [regex]::Replace($candidate, $truePattern, "pbCmdInProgress->store(true$storeOrder)")
    $candidate = [regex]::Replace($candidate, $falsePattern, "pbCmdInProgress->store(false$storeOrder)")
    if ((Mask-GuardOrder $candidate) -cne (Mask-GuardOrder $original)) {
      throw "Guard fixture changed code outside the four memory-order arguments: $variant"
    }
    [IO.File]::WriteAllText($commandFile, $candidate, $utf8)
  }

  if ($MingwDirectory) {
    # MSVC compiles the original headers unchanged. Optional MinGW validation
    # requires only syntax/CRT portability changes, identical in all variants.
    $path = Join-Path $util 'util_bridgecommand.h'
    [IO.File]::WriteAllText($path, [IO.File]::ReadAllText($path).Replace(
      'std::is_base_of<BridgeId::_Bridge, BRIDGE_ID>', 'std::is_base_of<::BridgeId::_Bridge, BRIDGE_ID>'), $utf8)
    $path = Join-Path $util 'util_circularbuffer.h'
    $text = [IO.File]::ReadAllText($path).Replace('using CircularQueue::', 'using CircularQueue<T>::').Replace(
      '      CircularQueue(name,', '      CircularQueue<T>(name,')
    $text = $text.Replace('    using BaseType = T;', "    using BaseType = T;`n    using CircularQueue<T>::m_data;`n    using CircularQueue<T>::m_pos;`n    using CircularQueue<T>::m_size;`n    using CircularQueue<T>::m_name;")
    [IO.File]::WriteAllText($path, $text, $utf8)
    $path = Join-Path $util 'util_circularqueue.h'
    [IO.File]::WriteAllText($path, [IO.File]::ReadAllText($path).Replace('std::exception("', 'std::runtime_error("'), $utf8)
    $path = Join-Path $util 'util_guid.h'
    [IO.File]::WriteAllText($path, [IO.File]::ReadAllText($path).Replace('_snprintf_s(', 'std::snprintf('), $utf8)
    # USE_BLOCKING_QUEUE is forbidden by prelude.h; exclude only this unselected
    # alternative. The actual AtomicCircularQueue and NamedSemaphore remain.
    [IO.File]::WriteAllText((Join-Path $util 'util_blockingcircularqueue.h'),
      "#pragma once`n#include `"util_semaphore.h`"`n", $utf8)
  }
  if ($variant -eq 'current' -and
      (Get-FileHash -LiteralPath $commandFile -Algorithm SHA256).Hash -ne $sourceHashes['util_bridgecommand.cpp']) {
    throw 'Current Command translation unit is not byte-identical to production'
  }
  if ((Mask-GuardOrder ([IO.File]::ReadAllText($commandFile))) -cne (Mask-GuardOrder $original)) {
    throw "Command translation unit differs beyond the guard memory orders: $variant"
  }

  $adapterSource = Join-Path $support 'diagnostic_adapters.cpp'
  $prelude = Join-Path $support 'prelude.h'
  $productionSources = @($commandFile, (Join-Path $util 'util_sharedmemory.cpp'), (Join-Path $util 'util_semaphore.cpp'))
  Push-Location $output
  try {
    if ($MingwDirectory) {
      $flags = @('-std=c++17', '-O2', '-DNDEBUG', '-pthread', '-static', '-municode',
        '-include', $prelude, '-I', $util, '-I', $support)
      & $compiler @flags $testSource $adapterSource @productionSources -lole32 -o command-guard.exe
      if ($LASTEXITCODE -ne 0) { throw "MinGW Command guard build failed: $variant / $CompileArchitecture" }
    } else {
      $flags = @('/nologo', '/std:c++17', '/EHsc', '/O2', '/MT', '/DNDEBUG', '/W4', '/WX',
        "/FI$prelude", "/I$util", "/I$support")
      foreach ($translationUnit in @($testSource, $adapterSource)) {
        & $compiler @flags /c $translationUnit
        if ($LASTEXITCODE -ne 0) { throw "Command guard test build failed: $translationUnit / $CompileArchitecture" }
      }
      foreach ($translationUnit in $productionSources) {
        # Existing upstream conversions, signed comparisons, and assert-only
        # parameters. Keep /WX and do not suppress these in the test logic.
        $productionWarnings = @('/wd4018', '/wd4100', '/wd4244', '/wd4267', '/wd4389')
        if ([IO.Path]::GetFileName($translationUnit) -eq 'util_sharedmemory.cpp') { $productionWarnings += '/wd4189' }
        & $compiler @flags @productionWarnings /c $translationUnit
        if ($LASTEXITCODE -ne 0) { throw "Actual production Command/IPC build failed: $translationUnit / $CompileArchitecture" }
      }
      & $compiler /nologo command_guard_ipc.obj diagnostic_adapters.obj util_bridgecommand.obj util_sharedmemory.obj util_semaphore.obj ole32.lib /Fe:command-guard.exe
      if ($LASTEXITCODE -ne 0) { throw "Command guard link failed: $variant / $CompileArchitecture" }
    }
    if ((Get-FileHash -LiteralPath $testSource -Algorithm SHA256).Hash -ne $harnessHash) {
      throw 'Command guard harness changed during compilation; rebuild before running'
    }
    [ordered]@{
      variant = $variant
      architecture = $CompileArchitecture
      compiler = $compiler
      compiler_version = (Get-Item -LiteralPath $compiler).VersionInfo.FileVersion
      flags = $flags
      source = $source
      source_sha256 = $sourceHashes
      command_translation_unit_sha256 = (Get-FileHash -LiteralPath $commandFile -Algorithm SHA256).Hash
      harness_sha256 = $harnessHash
      support_sha256 = $supportHashes
      executable_sha256 = (Get-FileHash -LiteralPath 'command-guard.exe' -Algorithm SHA256).Hash
      mingw_header_adaptations = [bool]$MingwDirectory
      boundary = 'Full production Command TU, IpcChannel, queues, SharedMemory and NamedSemaphore. Only four Command guard order arguments may differ; config/logger/disabled external observers/Tracy are test adapters. No graphics backend or lifecycle callbacks.'
    } | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath 'build-metadata.json' -Encoding UTF8
  } finally { Pop-Location }
  Write-Output "Built actual Command/IPC: $variant / $CompileArchitecture"
}
